mapper.select:
select  from basket_discipline_record
where season_id = #{seasonId} and discipline_status = 1 and record_status = 'ACTIVE' and is_delete = 0
  and effective_start_time <= #{now}
  and (effective_end_time is null or effective_end_time >= #{now})
  and member_id in
#{mid}

select d.id, d.record_no as recordNo, d.target_type as targetType, d.season_id as seasonId,
       s.season_name as seasonName, d.team_id as teamId, t.team_name as teamName,
       d.player_id as playerId, p.player_no as playerNo, d.member_id as memberId,
       d.discipline_type as disciplineType, d.penalty_code as penaltyCode, d.title,
       d.discipline_status as disciplineStatus, d.record_status as recordStatus,
       d.match_suspension_remaining as matchSuspensionRemaining, d.point_deduction as pointDeduction,
       d.effective_start_time as effectiveStartTime, d.effective_end_time as effectiveEndTime,
       d.decision_time as decisionTime, d.create_time as createTime
from basket_discipline_record d
left join basket_tournament_season s on s.id = d.season_id and s.is_delete = 0
left join basket_team t on t.id = d.team_id and t.is_delete = 0
left join basket_player_profile p on p.id = d.player_id and p.is_delete = 0
where d.is_delete = 0
and d.season_id = #{seasonId}
and s.tournament_id = #{tournamentId}
and d.team_id = #{teamId}
and d.player_id = #{playerId}
and d.member_id = #{memberId}
and d.target_type = #{targetType}
and d.record_status = #{recordStatus}
and d.penalty_code = #{penaltyCode}

    and (d.record_no like concat('%', #{keyword}, '%') or d.title like concat('%', #{keyword}, '%'))

order by d.create_time desc, d.id desc
